MATCH (c:Circular)-[:CONTAINS]->(cl:Clause)-[:REFERENCES]->(e:Entity)
WHERE toLower(e.name) CONTAINS 'sebi' AND toLower(e.name) CONTAINS 'foreign' AND toLower(e.name) CONTAINS 'portfolio' AND toLower(e.name) CONTAINS 'investors' AND toLower(e.name) CONTAINS 'regulations' AND toLower(e.name) CONTAINS '2019'
RETURN c.id, cl.text, cl.page_number, e.name;

MATCH (c)-[:CONTAINS]->(cl)-[:REFERENCES]->(e)
WHERE toLower(e.name) CONTAINS 'debenture' AND toLower(e.name) CONTAINS 'regulations'
RETURN c.id, cl.text, cl.page_number, e.name;

MATCH (c:Circular)-[:CONTAINS]->(cl:Clause) 
WHERE cl.text CONTAINS 'October 30, 2026' OR cl.text CONTAINS 'Oct 30, 2026' 
RETURN c.id, cl.text, cl.page_number;

MATCH (c)-[:CONTAINS]->(cl)
WHERE toLower(cl.text) CONTAINS 'companies' AND toLower(cl.text) CONTAINS 'act' AND toLower(cl.text) CONTAINS '2013'
RETURN c.id, cl.text, cl.page_number;
